        response = await self.http_client.send_async("POST", path, body=input)

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "POST",
                path,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)
